import "server-only";
import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import path from "node:path";
import type { FileStorage } from "./index";

/** Keys are generated by the app: 32 hex characters plus an extension. */
const KEY_PATTERN = /^[a-f0-9]{32}\.[a-z0-9]{2,5}$/;

/**
 * Stores files in a folder on the server's disk.
 *
 * The folder sits outside `public/`, so the web server never serves it
 * directly. It must survive restarts and redeploys, which rules out most
 * serverless hosts (see docs/deployment.md).
 */
export class LocalDiskStorage implements FileStorage {
  private readonly root: string;

  constructor(directory: string) {
    this.root = path.resolve(directory);
  }

  private pathFor(key: string): string {
    // Rejecting anything but our own key format means a key can never
    // contain "../" and escape the upload folder.
    if (!KEY_PATTERN.test(key)) throw new Error("Invalid storage key.");
    return path.join(this.root, key);
  }

  async put(key: string, data: Buffer): Promise<void> {
    const target = this.pathFor(key);
    await mkdir(this.root, { recursive: true });
    // "wx" refuses to overwrite an existing file.
    await writeFile(target, data, { flag: "wx", mode: 0o600 });
  }

  async get(key: string): Promise<Buffer | null> {
    try {
      return await readFile(this.pathFor(key));
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
      throw error;
    }
  }

  async delete(key: string): Promise<void> {
    await rm(this.pathFor(key), { force: true });
  }
}
